import"./modulepreload-polyfill-B5Qt9EMX.js";import{m as s}from"./foundation-module-BgS6mBLm.js";import{h as r,p as a,i as e}from"./content-helpers-BfuPXrd1.js";const o='<article class="fm-source-card"><p><strong>School Energy Guide</strong></p><p>By Ana Ruiz, energy educator · Updated March 2026</p><p>The guide explains classroom energy use and links to the national energy agency dataset.</p><p>Purpose: help schools reduce wasted electricity.</p></article>',n={id:"MOD-SOURCE-CREDIBILITY-01",slug:"source-credibility",version:"0.1.0",storageKey:"mod-source-credibility-01-v0.1.0",mark:"SRC",shortTitle:"Source credibility",title:"Credible Sources, Licensing, and Credit",gradeLabel:"Grades 7–9 Technology",classes:["7A","7B","8A","8B","9A","9B"],sections:[{id:"start",short:"Start",title:"Check before you use",summary:"Evaluate a source, identify its purpose, and credit words, data, and media correctly.",minutes:5,html:`<section class="fm-opening"><div><p class="fm-label">Goal</p><h2>A useful source leaves evidence you can check</h2><p>Do not trust a page because it looks polished. Check who made it, when it was updated, what evidence it uses, and why it exists.</p></div>${o}</section><section class="fm-block"><p class="fm-label">Before you begin</p><h2>What you need and what you will save</h2><div class="fm-concept-grid"><div><h3>Know</h3><p>A source is where information, data, or media came from.</p></div><div><h3>Use</h3><p>A computer and three teacher-assigned source cards or links.</p></div><div><h3>Check</h3><p>Author, date, evidence, purpose, permission, and credit details.</p></div><div><h3>Save</h3><p>A three-source decision, one complete credit, and this practice report.</p></div></div></section>`},{id:"credibility-learn",short:"Learn checks",title:"Use four credibility checks",summary:"Inspect author, date, evidence, and purpose.",minutes:15,html:`<section class="fm-block"><p class="fm-label">Learn</p><h2>Ask the same four questions every time</h2>${o}<div class="fm-concept-grid"><div><h3>Author</h3><p>Who is responsible, and what relevant knowledge do they show?</p></div><div><h3>Date</h3><p>Is the information current enough for your question?</p></div><div><h3>Evidence</h3><p>Can you follow the data, references, or examples?</p></div><div><h3>Purpose</h3><p>Is the page informing, selling, persuading, or entertaining?</p></div></div></section>`},a("credibility-practice","Source practice","Practice credibility checks","Choose the evidence that best supports a source decision.",[e("Check the author","Which detail best helps you evaluate the author?",["Relevant role and named organization","A colorful profile picture","A short username"],0,"Evaluate author responsibility","A relevant role and organization can be checked.","Choose evidence connected to expertise and accountability."),e("Check the date","A page gives current browser-security advice but has no update date. What should you do?",["Find a current dated source","Assume it is current","Use it because it is short"],0,"Evaluate currency","Security advice changes, so a current dated source is safer.","Ask whether old information could cause a wrong decision."),e("Check evidence","Which page provides stronger evidence?",["A page linking its dataset and method","A page saying everyone knows","A page with many animations"],0,"Trace supporting evidence","A dataset and method let you check how the claim was produced.","Look for information another person can verify."),e("Check purpose","A product page says its own app is the best. Which purpose matters most?",["Selling","Teaching a neutral lesson","Archiving records"],0,"Recognize commercial purpose","The company benefits when readers buy the app.","Ask what the publisher wants the reader to do."),e("Make a decision","The energy guide names an educator, a 2026 date, an agency dataset, and an educational purpose. What is the best judgment?",["Credible for a school-energy starting point","Automatically perfect for every claim","Unusable because it has a title"],0,"Make a limited credibility judgment","The checks support using it as a starting point, while important claims can still be confirmed.","Credibility is connected to a specific use.")]),{id:"credit-learn",short:"Learn credit",title:"Use media with permission and credit",summary:"Separate ownership, license, and source credit.",minutes:15,html:'<section class="fm-block"><p class="fm-label">Learn</p><h2>Finding an image does not grant permission</h2><div class="fm-concept-grid"><div><h3>Copyright</h3><p>The creator controls how original work is used.</p></div><div><h3>License</h3><p>The stated rules for reuse.</p></div><div><h3>Creative Commons</h3><p>A family of licenses with specific conditions.</p></div><div><h3>Credit</h3><p>Creator, work title, source link, and license when available.</p></div></div><p class="fm-note">Use teacher-provided media, your own work, public-domain media, or media whose license permits the planned use.</p></section>'},a("credit-practice","Credit practice","Practice licensing and credit","Choose the safe and complete media decision.",[e("Search result","An image appears in search results with no license information. What should you do?",["Open the source and check permission","Copy it immediately","Remove the creator name"],0,"Check the original source","The source page should state ownership or reuse conditions.","A search preview is not a license."),e("Credit fields","Which credit is most complete?",["Photo by Lina Chen, “Solar Roof,” source link, CC BY 4.0","Image from internet","Google picture"],0,"Write a traceable credit","The first credit names creator, work, source, and license.","A reader should be able to find the original."),e("Public domain","What does public domain usually allow?",["Reuse without copyright permission","Claiming you created it","Ignoring any teacher source rule"],0,"Understand public domain","Public-domain work may be reused, but honest source credit is still good practice.","Permission and authorship are different questions."),e("CC BY","What is the main condition of a CC BY license?",["Give attribution","Never share the work","Pay the search engine"],0,"Read a license condition","BY requires credit to the creator.","The letters name the condition."),e("Own media","You made the diagram yourself. How should the project identify it?",["Original diagram by the student","Unknown source","No statement is allowed"],0,"Identify original work","A short original-work note distinguishes it from reused media.","State who created it.")]),{id:"source-record",short:"Record check",title:"Record a three-source decision",summary:"Apply the same checks and select the source that fits your question.",minutes:20,kind:"form",prompt:"Record your source evaluation",fields:[{name:"question",label:"Research question"},{name:"sources",label:"List the three assigned source titles and links.",type:"textarea",rows:4},{name:"checks",label:"For each source, record author, date, evidence, and purpose.",type:"textarea",rows:6},{name:"decision",label:"Which source is most useful, and why? Write two evidence-based sentences.",type:"textarea",rows:4},{name:"credit",label:"Write one complete media or data credit.",type:"textarea",rows:3}]},{id:"review",short:"Review",title:"Check the source decision before you submit",summary:"Review credibility, permission, credit, and saved links.",minutes:10,html:'<section class="fm-block"><p class="fm-label">Review</p><h2>Can another person verify your decision?</h2><ul class="fm-checklist"><li>Each source has a title and a working link or printed source label.</li><li>The evaluation records author, date, evidence, and purpose.</li><li>The final choice explains why the source fits the research question.</li><li>Reused media has permission for the planned use.</li><li>The credit names the creator, work, source, and license when available.</li></ul></section><section class="fm-block"><p class="fm-label">Common mistakes</p><h2>Fix these before exporting</h2><div class="fm-concept-grid"><div><h3>Looks professional</h3><p>Appearance is not evidence. Check who created the information and what supports it.</p></div><div><h3>No date</h3><p>For a topic that changes, replace an undated page with a current dated source.</p></div><div><h3>Credits Google</h3><p>Credit the creator and original source, not the search engine.</p></div><div><h3>Absolute claim</h3><p>State that a source is useful for a specific question, not perfect for every purpose.</p></div></div></section><section class="fm-note"><strong>Next:</strong> revisit the source or credit practice if a check is missing. Then open History & export and download the report your teacher assigned.</section>'},r]};s(n);document.addEventListener("submit",i=>{if(i.target.id!=="fm-choice-form"||i.target.querySelector('input[name="answer"]:checked'))return;i.preventDefault(),i.stopImmediatePropagation();const t=i.target.querySelector('input[name="answer"]');t.setCustomValidity("Choose an answer before saving."),t.reportValidity(),t.addEventListener("change",()=>t.setCustomValidity(""),{once:!0})},!0);
